function choosePlayer(index){const current=state.squad.find(p=>p.id===state.lineup[index]);const options=state.squad.map(p=>`${p.id}: ${p.name} (${p.pos} · OVR ${p.ovr})`).join('\n');let answer=prompt(`Trocar ${current?.name||'jogador'} por qual número?\n\n${options}`);if(answer===null)return;let id=Number(answer.split(':')[0]);if(!state.squad.some(p=>p.id===id)||state.lineup.includes(id)){notify('Jogador inválido ou já está em campo.');return}state.lineup[index]=id;save();renderPitch();notify('Escalação atualizada.')}
function addToLineup(id){let p=state.squad.find(x=>x.id===id);let eligible=state.lineup.map((id,i)=>({i,p:state.squad.find(x=>x.id===id)})).filter(x=>x.p?.pos===p.pos);let index=eligible.length?eligible[eligible.length-1].i:state.lineup.length-1;let old=state.squad.find(x=>x.id===state.lineup[index]);state.lineup[index]=id;save();renderPitch();notify(`${p.name} entrou no lugar de ${old.name}.`)}
